"""Independent UI assertions on committed dist; explicitly scripted HTTP states."""
import json,subprocess
from pathlib import Path
OUT=Path(__file__).resolve().parent; ROOT=OUT.parents[3]; LOG=[]; RESULTS=[]
def run(*args,code=None):
 p=subprocess.run(['agent-browser','--session','nova-qa09',*args],input=code,text=True,capture_output=True,timeout=60)
 LOG.append({'args':args,'stdout':p.stdout,'stderr':p.stderr,'exit':p.returncode});(OUT/'takeover-scripted-commands.json').write_text(json.dumps(LOG,ensure_ascii=False,indent=2))
 if p.returncode:raise RuntimeError(p.stdout+p.stderr)
 return p.stdout

def js(code):return run('eval','--stdin',code=code)
def check(name,expr):
 data=json.loads(js('(()=>{const result=('+expr+');return {name:'+json.dumps(name)+',pass:!!result}})()'));RESULTS.append(data);(OUT/'takeover-scripted-results.json').write_text(json.dumps(RESULTS,indent=2));return data

def click(sel):js('document.querySelector('+json.dumps(sel)+').scrollIntoView({block:"center"})');run('click',sel)
def shot(name):run('screenshot',str(OUT/('takeover-scripted-'+name+'.png')))
def ready():run('wait','--fn',"!document.querySelector('#question').disabled")
def ask(scenario='q3',text='QA09 independent UI state probe'):
 js('window.__t09.scenario='+json.dumps(scenario));run('fill','#question',text);click('button[type=submit]');run('wait','--fn',"document.querySelector('article:last-child .question-heading')?.textContent==="+json.dumps('問題過長' if scenario=='rejected' else text));
 if scenario not in ['provisional','retry']:ready()
def custom(answer,spans):
 js('window.__t09.customAnswer='+json.dumps(answer)+';window.__t09.customSpans='+json.dumps(spans));ask('custom')
run('reload');run('set','viewport','1280','720')
fixture=(ROOT/'docs/verification/ticket-09/scripted-events.js').read_text();js(fixture)
js('window.__t09.uploadHold=true');run('upload','#document',str(ROOT/'data/lightrag.pdf'));run('wait','--text','18 / 52')
check('processing disables composer with visible progress',"document.querySelector('#question').disabled && document.querySelector('progress').value===18 && document.querySelector('.composer').textContent.includes('Document')");shot('progress');js('window.__t09.release()');ready()
for i in range(6):ask('q3','Summarize ordinary measurements round '+str(i+1))
js('document.querySelector("#question").scrollIntoView({block:"center"})')
geometry=json.loads(js("(()=>{const p=document.querySelector('.document-overview'),r=p.getBoundingClientRect(),a=p.querySelector('.answer-text').getBoundingClientRect();return {viewport:[innerWidth,innerHeight],scrollY,top:r.top,bottom:r.bottom,readable:Math.min(a.bottom,r.bottom,innerHeight)>Math.max(a.top,r.top,0),count:document.querySelectorAll('article').length}})()"));(OUT/'takeover-scripted-overview.json').write_text(json.dumps(geometry,indent=2));check('six ordinary turns overview visible',f"{str(geometry['readable']).lower()} && {geometry['top']}>=0 && {geometry['bottom']}<=innerHeight");shot('six-turn-overview')
click('article:last-child .trace > summary');check('thinking collapsed by default',"[...document.querySelectorAll('article:last-child .thinking-content')].every(x=>!x.open)");click('article:last-child .thinking-content > summary');check('thinking expands',"document.querySelector('article:last-child .thinking-content').open");shot('thinking')
ask('budget');click('article:last-child .trace > summary');check('fixed10K meter and proportional near-budget bar',"(()=>{const ms=[...document.querySelectorAll('article:last-child [role=meter]')];return ms.length===2&&ms.every(m=>m.getAttribute('aria-valuemax')==='10000')&&ms[1].getAttribute('aria-valuenow')==='9990'&&Math.abs(ms[1].querySelector('.token-prompt').getBoundingClientRect().width/ms[1].getBoundingClientRect().width-.699)<.01})()");shot('meters')
ask('provisional');run('wait','--fn',"!!document.querySelector('article:last-child .stage-answering')");check('provisional Citation clickable before final',"!!document.querySelector('article:last-child .provisional-text .inline-citation') && document.querySelector('article:last-child .answer-status').textContent.includes('Provisional')");click('article:last-child .inline-citation');run('wait','dialog .source-text');check('source full page range',"document.querySelector('#source-title').textContent.includes('pp.8–9')");run('press','Tab');check('modal focus contained',"!!document.activeElement.closest('dialog')");run('press','Escape');check('Escape returns focus',"!document.querySelector('dialog')&&document.activeElement.classList.contains('inline-citation')");shot('provisional');js('window.__t09.release()');ready();check('final removes provisional style',"!!document.querySelector('article:last-child .stage-complete')&&!document.querySelector('article:last-child .provisional-text')")
ask('retry');run('wait','--fn',"!!document.querySelector('article:last-child .stage-retry')");check('retry clears tentative first answer',"!document.querySelector('article:last-child .answer-text')?.textContent && document.querySelector('article:last-child .answer-status').textContent.includes('重新產生中')");shot('retry');js('window.__t09.release()');ready();check('retry final replaces initial text',"document.querySelector('article:last-child .answer-text').textContent.includes('Mix')")
ask('error');check('double length failure clears answer',"!!document.querySelector('article:last-child .error-state button')&&!document.querySelector('article:last-child .answer-text')?.textContent");shot('error');js("window.__t09.scenario='q3'");click('article:last-child .error-state button');ready();check('visible retry recovers',"!!document.querySelector('article:last-child .stage-complete')&&!document.querySelector('article:last-child .error-state')")
ask('rejected','Edit this overlong question');check('rejected input retained',"document.querySelector('#question').value==='Edit this overlong question' && document.querySelector('article:last-child .error-state').textContent.includes('1,000')")
ask('markdown');check('Markdown safe without executable script/unsafe scheme',"!window.__unsafe&&!document.querySelector('article:last-child .answer-text script')&&![...document.querySelectorAll('article:last-child .answer-text a')].some(a=>(a.getAttribute('href')||'').startsWith('javascript:'))&&!!document.querySelector('article:last-child .answer-text table')");shot('safe-markdown')
ask('no-thinking');click('article:last-child .trace > summary');check('absent thinking no empty panel',"!document.querySelector('article:last-child .thinking-content')")
cases=[('LF','Bad R&amp;D claim.\nNext valid [C1].','Bad R&D claim.'),('CRLF','Bad R&amp;D claim.\r\nNext valid [C1].','Bad R&D claim.'),('CR','Bad R&amp;D claim.\rNext valid [C1].','Bad R&D claim.'),('mixed','- Earlier valid [C1].\r\n  Bad R&amp;D claim.\nNext valid [C1].','Bad R&D claim.'),('emoji','😀 Bad R&#38;D claim.\r\nNext valid [C1].','😀 Bad R&D claim.'),('quote','> Bad R&amp;D claim.\r\n> Next valid [C1].','Bad R&D claim.'),('escape','Bad 5 \\* 3 claim. Next valid [C1].','Bad 5 * 3 claim.')]
for name,answer,bad in cases:
 start=0 if name=='emoji' else answer.index('Bad');end=answer.index('.',start)+1;custom(answer,[{'start':start,'end':end}]);check('Unverified correct sentence '+name,"(()=>{const a=document.querySelector('article:last-child .answer-text'),m=a.querySelector('.unverified-mark');return a.querySelectorAll('.unverified-mark').length===1&&m.previousSibling.textContent.trim().endsWith("+json.dumps(bad)+")&&m.nextSibling.textContent.trim().startsWith('Next valid')&&!!a.querySelector('.inline-citation')})()");shot('marker-'+name)
custom('Uncited transition.\n\n文件中未提及。\n\nVerified [C1].',[]);check('D01 uncited/refusal sentences unmarked',"!document.querySelector('article:last-child .unverified-mark')")
# Typed sources use distinct IDs and preserve all summary coverage fields.
js("""(()=>{const original=window.fetch;window.__qaSource=null;window.fetch=async(u,o)=>String(u).startsWith('/api/sources/')?Response.json(window.__qaSource||window.__t09.chunk):original(u,o)})()""")
for kind in ['section','group','document']:
 source={'id':'qa-summary','kind':kind,'section':'QA '+kind,'page_start':2,'page_end':12,'text':'Independent UI summary provenance fixture','section_titles':['Section Alpha','Section Omega']};js('window.__qaSource='+json.dumps(source));click('article:last-child .inline-citation');run('wait','dialog .source-text');check(kind+' source range and coverage',"document.querySelector('#source-title').textContent.includes('pp.2–12')&&document.querySelectorAll('dialog ul[aria-label="+'"Covered Sections"'+"] li').length===2&&document.querySelector('dialog').textContent.includes("+json.dumps(kind.title()+' Summary')+")");shot('source-'+kind);run('press','Escape')
source={'id':'qa-table','section_id':'q','section':'QA Uncertain','page_start':3,'page_end':4,'order':0,'text':'Raw ambiguous table 64.8 60.0','kind':'table','table_reconstructed':False};js('window.__qaSource='+json.dumps(source));click('article:last-child .inline-citation');run('wait','dialog .source-text');check('uncertain table warns and preserves raw source',"document.querySelector('.table-limitation').textContent.includes('結構未能可靠重建')&&document.querySelector('dialog .source-text').textContent==='Raw ambiguous table 64.8 60.0'&&!document.querySelector('dialog table')");shot('uncertain');run('press','Escape')
for w,h in [(1440,900),(1280,720),(390,844)]:
 run('set','viewport',str(w),str(h));js('document.querySelector("article:last-child .answer-text").scrollIntoView({block:"center"})');check('readable no overflow '+str(w),"document.documentElement.scrollWidth<=innerWidth&&parseFloat(getComputedStyle(document.body).fontSize)>=15&&parseFloat(getComputedStyle(document.body).fontSize)<=16");shot('responsive-'+str(w))
run('set','viewport','1280','720')
# Controlled stale fetch cannot reopen a closed source dialog.
js("""(()=>{const f=window.fetch;window.fetch=async(u,o)=>{if(String(u).startsWith('/api/sources/')){await new Promise(r=>window.__qaRelease=r);return Response.json(window.__t09.chunk)}return f(u,o)}})()""");click('article:last-child .inline-citation');run('wait','dialog');click('dialog .secondary-button');js('window.__qaRelease()');run('wait','--fn',"!document.querySelector('dialog')");check('late source cannot reopen closed dialog',"!document.querySelector('dialog')")
# Upload reconnection / restart through visible controls.
js('window.__t09.progressLost=true');run('upload','#document',str(ROOT/'data/lightrag.pdf'));run('wait','--text','Reconnect upload progress');js("window.__t09.progressLost='restart'");click('.upload .secondary-button');run('wait','--text','Choose the PDF again.');check('restart404 clears stale states',"document.querySelector('#question').disabled&&!document.querySelector('article')&&!document.querySelector('.document-overview')&&!document.querySelector('dialog')&&!document.querySelector('#document').disabled");shot('restart404');js('window.__t09.progressLost=false;window.__t09.uploadHold=false');run('upload','#document',str(ROOT/'data/lightrag.pdf'));ready();check('restart reupload recovers',"!!document.querySelector('.document-overview')&&!document.querySelector('#question').disabled")
run('console');run('errors')
